//! World-map overlay masks generated by the original hr scale handler.
use crate::{Error, Result};
pub fn mask(size: usize, mut shape: u8, mut rotation: u8) -> Result<Vec<u8>> {
    if !(1..=64).contains(&size) || !(1..=11).contains(&shape) || rotation > 3 {
        return Err(Error::Invalid("map tile mask"));
    }
    match shape {
        9 => {
            shape = 1;
            rotation = (rotation + 1) & 3;
        }
        10 => {
            shape = 1;
            rotation = (rotation + 3) & 3;
        }
        11 => {
            shape = 8;
            rotation = (rotation + 3) & 3;
        }
        _ => {}
    }
    let n = size as i32;
    let mut pixels = Vec::with_capacity(size * size);
    for y in 0..n {
        for x in 0..n {
            let rx = n - 1 - x;
            let ry = n - 1 - y;
            let on = match shape {
                1 => match rotation {
                    0 => x <= y,
                    1 => x <= ry,
                    2 => x >= y,
                    _ => x >= ry,
                },
                2 | 4 => {
                    let (a, b) = match rotation {
                        0 => (x, ry),
                        1 => (x, y),
                        2 => (rx, y),
                        _ => (rx, ry),
                    };
                    if shape == 2 {
                        if rotation & 1 == 0 {
                            a <= b >> 1
                        } else {
                            a >= b << 1
                        }
                    } else if rotation & 1 == 0 {
                        a >= b >> 1
                    } else {
                        a <= b << 1
                    }
                }
                3 | 5 => {
                    let (a, b) = match rotation {
                        0 => (rx, ry),
                        1 => (x, ry),
                        2 => (x, y),
                        _ => (rx, y),
                    };
                    if shape == 3 {
                        if rotation & 1 == 0 {
                            a <= b >> 1
                        } else {
                            a >= b << 1
                        }
                    } else if rotation & 1 == 0 {
                        a >= b >> 1
                    } else {
                        a <= b << 1
                    }
                }
                6 => match rotation {
                    0 => x <= n / 2,
                    1 => y <= n / 2,
                    2 => x >= n / 2,
                    _ => y >= n / 2,
                },
                7 | 8 => {
                    let (a, b) = match rotation {
                        0 => (x, y),
                        1 => (x, ry),
                        2 => (rx, ry),
                        _ => (rx, y),
                    };
                    if shape == 7 {
                        a <= b - n / 2
                    } else {
                        a >= b - n / 2
                    }
                }
                _ => unreachable!(),
            };
            pixels.push(if on { 255 } else { 0 });
        }
    }
    Ok(pixels)
}

pub struct Masks {
    pub size: usize,
    tiles: Vec<Vec<u8>>,
}
impl Masks {
    pub fn new(size: usize) -> Result<Self> {
        let mut tiles = Vec::with_capacity(44);
        for shape in 1..=11 {
            for rotation in 0..4 {
                tiles.push(mask(size, shape, rotation)?);
            }
        }
        Ok(Self { size, tiles })
    }
    pub fn get(&self, shape: u8, rotation: u8) -> Result<&[u8]> {
        if !(1..=11).contains(&shape) || rotation > 3 {
            return Err(Error::Invalid("map tile mask"));
        }
        Ok(&self.tiles[(shape as usize - 1) * 4 + rotation as usize])
    }
}
